<div class="page-heading admin-heading"><div><span class="eyebrow">Access control</span><h1>Users & roles</h1><p>Granular role assignments keep staff and applicant records appropriately separated.</p></div><div class="heading-actions"><a class="button button-outline" href="<?= url('admin/roles') ?>">Manage permissions</a><a class="button button-primary" href="#create-user">+ Add staff user</a></div></div><div class="access-summary"><section class="card"><span class="eyebrow">Role catalogue</span><div class="role-chips"><?php foreach($roles as $role):?><span><?= e($role['name']) ?> <b><?= e($role['is_system']?'System':'Custom') ?></b></span><?php endforeach?></div></section><section class="card access-rule"><span>⌾</span><div><b>Least-privilege baseline</b><p>Super Admin can configure access. Sensitive application decisions, payment verification and audit records use separate permissions.</p></div></section></div><?php if(can('users.manage')):?><section class="card create-user-card" id="create-user"><div class="card-heading"><div><span class="eyebrow">Named staff access</span><h2>Create staff account</h2></div><small>Do not create shared logins.</small></div><form method="post" action="<?= url('admin/users') ?>"><?= csrf_field() ?><div class="form-grid three"><label><span>First name *</span><input name="first_name" value="<?= e(old('first_name')) ?>" required></label><label><span>Last name *</span><input name="last_name" value="<?= e(old('last_name')) ?>" required></label><label><span>Staff role *</span><select name="role_id" required><option value="">Choose role</option><?php foreach($roles as $role): if($role['slug']==='applicant')continue;?><option value="<?= e($role['id']) ?>"<?= selected(old('role_id'),$role['id']) ?>><?= e($role['name']) ?></option><?php endforeach?></select></label><label><span>Email *</span><input type="email" name="email" value="<?= e(old('email')) ?>" required><?= error('email')?'<small class="field-error">'.e(error('email')).'</small>':'' ?></label><label><span>Mobile</span><input name="mobile" value="<?= e(old('mobile')) ?>"></label><label><span>Temporary password *</span><input type="password" name="password" minlength="12" required><?= error('password')?'<small class="field-error">'.e(error('password')).'</small>':'' ?></label></div><div class="form-actions"><span>Use 12+ characters with upper/lower case, number and symbol.</span><button class="button button-primary button-sm">Create staff account</button></div></form></section><?php endif?><section class="card application-table-card"><div class="table-filters"><div class="search-field"><span>⌕</span><input placeholder="Search users by name or email"></div><select><option>All roles</option><?php foreach($roles as $role):?><option><?= e($role['name']) ?></option><?php endforeach?></select><select><option>All statuses</option><option>Active</option><option>Suspended</option></select></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Contact</th><th>Role(s)</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody><?php foreach($users as $user):?><tr><td><div class="person-cell"><span><?= e(strtoupper(substr($user['first_name'],0,1))) ?></span><div><b><?= e($user['first_name'].' '.$user['last_name']) ?></b><small>User #<?= e($user['id']) ?></small></div></div></td><td><?= e($user['email']) ?><small class="completion-small"><?= e($user['mobile']) ?></small></td><td><span class="role-pill"><?= e($user['roles']?:'No role') ?></span></td><td><span class="status-pill status-<?= e($user['status']) ?>"><?= e(ucfirst($user['status'])) ?></span></td><td><?= format_date($user['last_login_at'],true) ?></td><td><?php if(can('users.manage')&&!str_contains((string)$user['roles'],'Applicant')):?><details class="user-access-edit"><summary class="row-action">⋯</summary><form method="post" action="<?= url('admin/users/'.$user['id']) ?>"><?= csrf_field() ?><label>Role<select name="role_id"><?php foreach($roles as $role):if($role['slug']==='applicant')continue;?><option value="<?= e($role['id']) ?>"<?= selected(explode(',',(string)$user['role_ids'])[0]??'',$role['id']) ?>><?= e($role['name']) ?></option><?php endforeach?></select></label><label>Status<select name="status"><option value="active"<?= selected($user['status'],'active') ?>>Active</option><option value="suspended"<?= selected($user['status'],'suspended') ?>>Suspended</option></select></label><button class="button button-primary button-sm">Save access</button></form></details><?php else:?><span>—</span><?php endif?></td></tr><?php endforeach?></tbody></table></div></section>
